// ELEMENTS:
// 1. Fundo navy com um fio azul IAD que se desenha
// 2. Faixa de 3 fotos altas (src, src2, src3) que abrem de baixo e deslizam devagar para a esquerda
// 3. Label + legenda em serifa branca
// 4. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { MediaImg as Img } from "../media";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#161617";
const NAVY_RGB = "22,22,23";
const CYAN = "#FFFFFF";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.24) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const FaixaFilme: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const land = format === "landscape";
  const u = land ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const srcs = [p.src, p.src2, p.src3].map((s) => String(s ?? "")).filter(Boolean);
  const caption = String(anim.text ?? "").trim();
  const label = String(p.label ?? "").trim();

  const show = (delay: number, len = 0.8): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay, 0.7);
    return { opacity: t, transform: `translateY(${(1 - t) * 20 * u}px)` };
  };

  // A strip of tall frames gliding slowly to the left, like a film reel.
  const tileW = land ? W * 0.34 : W * 0.6;
  const tileH = land ? H * 0.6 : format === "half" ? H * 0.58 : H * 0.42;
  const gap = 28 * u;
  const pad = 80 * u;
  const stripW = srcs.length * tileW + (srcs.length - 1) * gap;
  const travel = Math.max(0, stripW - (W - 2 * pad));
  const x = interpolate(f, [0, T], [0, -travel], { ...clamp, easing: Easing.inOut(Easing.sin) });
  const track = show(0.2, 1.2);

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", backgroundColor: NAVY, overflow: "hidden", justifyContent: "center", gap: 56 * u }}>
      <div style={{ marginLeft: pad, width: (W - 2 * pad) * track, height: 2 * u, background: CYAN, opacity: 0.85 }} />
      <div style={{ display: "flex", gap, paddingLeft: pad, transform: `translateX(${x}px)` }}>
        {srcs.map((s, i) => {
          const open = show(0.1 + i * 0.22, 0.9);
          return (
            <div key={i} style={{ flex: "0 0 auto", width: tileW, height: tileH, overflow: "hidden", clipPath: `inset(${(1 - open) * 100}% 0 0 0)` }}>
              <Img src={s} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "saturate(0.88) contrast(1.05)", transform: `scale(${1.12 - 0.08 * open})` }} />
            </div>
          );
        })}
      </div>
      {caption || label ? (
        <div style={{ paddingLeft: pad, paddingRight: pad, display: "flex", flexDirection: "column", gap: 18 * u }}>
          {label ? (
            <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 36 * u, letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE, ...rise(0.8) }}>{label}</div>
          ) : null}
          {caption ? (
            <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 300, fontSize: 88 * u, lineHeight: 1.05, color: WHITE, ...rise(0.95) }}>{caption}</div>
          ) : null}
        </div>
      ) : null}
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default FaixaFilme;
